mapper.select:
SELECT cacf.finish_id, cacf.product_id, cacf.finish_amount, cacf.make_up, cacf.makeup_amount, cacf.contract_id, cacf.con_document_category, contract.contract_number, contract.contract_name, contract.approval_number, contract.uncollected_due_amount, contract.pre_clean_total_money, contract.pre_service_charge FROM ct_abs_contract_finish cacf left join ( select fc.contract_id, fc.contract_name, fc.contract_number, fc.approval_number, 'FCT_CONTRACT' con_document_category, fc.pre_clean_total_money, fc.pre_service_charge, nvl(cash.uncollected_due_amount,0) uncollected_due_amount from fct_contract fc left join ( select ca.contract_id, sum(ca.due_amount) uncollected_due_amount from fct_quotation_cashflow ca where ca.cf_status='BLOCK' and ca.cf_item in(54,55) group by ca.contract_id ) cash on cash.contract_id=fc.contract_id where fc.data_class='NORMAL' union all select fc.contract_id, fc.contract_name, fc.contract_number, pp.approval_number, 'CON_CONTRACT' con_document_category, fc.pre_clean_total_money, fc.pre_service_charge, nvl(cash.uncollected_due_amount,0) uncollected_due_amount from con_contract fc join prj_project pp on pp.project_id=fc.project_id left join ( select ca.contract_id, sum(ca.due_amount) uncollected_due_amount from con_contract_cashflow ca where ca.cf_status='BLOCK' and ca.cf_item=1 group by ca.contract_id ) cash on cash.contract_id=fc.contract_id where fc.data_class='NORMAL'
) contract on cacf.contract_id=contract.contract_id and cacf.con_document_category=contract.con_document_category where 1=1
and cacf.product_id = #{productId}
